// Generates src/i18n/messages.ts from locales/<lang>/*.ftl (the kernel runs under tsx: no import.meta.glob).
// `--check` exits 1 when the generated file is stale.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

export function generate() {
  const sources = {};
  for (const lang of readdirSync(join(root, "locales")).sort())
    sources[lang] = readdirSync(join(root, "locales", lang))
      .filter((f) => f.endsWith(".ftl"))
      .sort()
      .map((f) => "\n" + readFileSync(join(root, "locales", lang, f), "utf8"))
      .join("");
  return `// Generated by scripts/locales.mjs from locales/: do not edit.\nexport const KERNEL_SOURCES = ${JSON.stringify(sources, null, 2)} as const;\n`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const target = join(root, "src", "i18n", "messages.ts");
  const out = generate();
  if (process.argv.includes("--check")) {
    let current = "";
    try {
      current = readFileSync(target, "utf8");
    } catch {}
    if (current !== out) {
      console.error("messages.ts is stale: run `pnpm locales` in packages/kernel");
      process.exit(1);
    }
  } else writeFileSync(target, out);
}
